SELECT CASE WHEN COUNT(1) > 0 THEN TRUE ELSE FALSE END
FROM growth_reward_exchange
WHERE student_id = #{studentId}
  AND reward_id = #{rewardId}
  AND status IN ('PENDING_APPROVAL', 'PENDING_VERIFICATION')

SELECT 
FROM growth_reward_exchange
WHERE student_id = #{studentId}
ORDER BY requested_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM growth_reward_exchange
WHERE student_id = #{studentId}

mapper.update:
UPDATE growth_reward_exchange
SET status = 'PENDING_VERIFICATION',
    reviewed_by = #{reviewedBy},
    reviewed_at = #{reviewedAt},
    version_no = version_no + 1,
    updated_at = #{reviewedAt}
WHERE id = #{id}
  AND status = 'PENDING_APPROVAL'
  AND version_no = #{expectedVersion}

UPDATE growth_reward_exchange
SET status = 'REJECTED',
    reviewed_by = #{reviewedBy},
    reviewed_at = #{reviewedAt},
    reject_reason = #{rejectReason},
    version_no = version_no + 1,
    updated_at = #{reviewedAt}
WHERE id = #{id}
  AND status = 'PENDING_APPROVAL'
  AND version_no = #{expectedVersion}

UPDATE growth_reward_exchange
SET status = 'VERIFIED',
    verified_by = #{verifiedBy},
    verified_at = #{verifiedAt},
    version_no = version_no + 1,
    updated_at = #{verifiedAt}
WHERE id = #{id}
  AND status = 'PENDING_VERIFICATION'
  AND version_no = #{expectedVersion}

mapper.select:
SELECT id
FROM growth_reward_exchange
WHERE status = 'PENDING_APPROVAL'
  AND approval_deadline <= #{now}
ORDER BY approval_deadline, id
LIMIT #{limit}

mapper.update:
UPDATE growth_reward_exchange
SET status = 'AUTO_REJECTED',
    version_no = version_no + 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND status = 'PENDING_APPROVAL'
  AND approval_deadline <= #{updatedAt}

UPDATE growth_reward_exchange
SET status = 'EXPIRED',
    version_no = version_no + 1,
    updated_at = #{updatedAt}
WHERE reward_id = #{rewardId}
  AND status = 'PENDING_APPROVAL'
